/**
 * Adiciona o bloco de CSS elaborado para a formatação do post.
 */
const addElaborateCSS = (htmlContent) => {
    const wpStyles = `
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap');
        .wp-content-wrapper {
            max-width: 800px;
            margin: 0 auto;
            font-family: 'Poppins', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            line-height: 1.8;
            font-size: 20px;
            color: #3d3d3d;
        }
        .wp-content-wrapper h1, .wp-content-wrapper h2, .wp-content-wrapper h3 {
            color: #2c3e50;
            line-height: 1.4;
            font-weight: 700;
        }
        .wp-content-wrapper h1 {
            font-size: 2.8rem;
            border-bottom: 3px solid #3498db;
            padding-bottom: 15px;
            margin-bottom: 30px;
        }
        .wp-content-wrapper h2 {
            font-size: 2.2rem;
            margin-top: 50px;
            margin-bottom: 20px;
        }
        .wp-content-wrapper h3 {
            font-size: 1.8rem;
            margin-top: 40px;
            margin-bottom: 15px;
            padding-left: 20px;
            border-left: 5px solid #3498db;
        }
        .wp-content-wrapper p {
            margin-bottom: 20px;
        }
        .wp-image-container {
            margin: 40px 0;
            text-align: center;
        }
        .wp-image {
            max-width: 100%;
            height: auto;
            border-radius: 12px;
            box-shadow: 0 8px 25px rgba(0,0,0,0.15);
        }
    </style>
    `;
    return wpStyles + htmlContent;
};

/**
 * Prepara o HTML com uma lógica de limpeza robusta e completa.
 */
const processHTMLForWordPress = (rawHtml) => {
    let cleanHtml = rawHtml;

    // Remove tags de documento HTML, se existirem
    cleanHtml = cleanHtml.replace(/<!DOCTYPE.*?>/i, '').replace(/<html[^>]*>/i, '').replace(/<\/html>/i, '').replace(/<head[^>]*>.*?<\/head>/is, '').replace(/<body[^>]*>/i, '').replace(/<\/body>/i, '').replace(/<meta[^>]*>/gi, '');

    // Converte listas (ordenadas ou não) em parágrafos
    cleanHtml = cleanHtml.replace(/<\/(ul|ol)>/gi, '');
    cleanHtml = cleanHtml.replace(/<(ul|ol)[^>]*>/gi, '');
    cleanHtml = cleanHtml.replace(/<li>/gi, '<p>');
    cleanHtml = cleanHtml.replace(/<\/li>/gi, '</p>');

    // Remove links que apontam para a Wikipedia
    cleanHtml = cleanHtml.replace(/<a[^>]+href=["'][^"']*wikipedia\.org[^"']*["'][^>]*>.*?<\/a>/gi, '');
    // Remove possíveis textos residuais como "(pt.wikipedia.org)"
    cleanHtml = cleanHtml.replace(/\(\s*pt\.wikipedia\.org\s*\)/gi, '');

    // Itera sobre cada título (h1 a h6) para limpá-lo de forma precisa
    cleanHtml = cleanHtml.replace(/(<h([1-6])>)(.*?)(<\/h\2>)/gi, (match, openTag, tagNumber, content, closeTag) => {
        let newContent = content;

        // Remove a numeração (ex: "1.", "1.1.") do início do conteúdo do título
        newContent = newContent.trim().replace(/^\d+(\.\d+)*\.\s*/, '');

        // Verifica se o conteúdo restante é APENAS "Introdução" ou "Conclusão"
        if (/^(Introdução|Conclusão)$/i.test(newContent.trim())) {
            return ''; // Retorna uma string vazia para apagar o título inteiro
        }

        // Retorna o título com o conteúdo já limpo
        return openTag + newContent + closeTag;
    });

    // Envolve as imagens em um container para aplicar margens e estilos
    cleanHtml = cleanHtml.replace(/<img[^>]*>/g, (match) => {
        const styledImg = match.replace('<img', '<img class="wp-image"');
        return `<div class="wp-image-container">${styledImg}</div>`;
    });

    // Envolve todo o conteúdo em um container principal para aplicar os estilos globais
    return `<div class="wp-content-wrapper">${cleanHtml}</div>`;
};

// Bloco de Execução Principal
try {
    // Ajuste o nome do nó 'Markdown' se o seu for diferente.
    const inputNode = $('Markdown');
    const htmlContent = inputNode.item.json.data;
    const markdownText = inputNode.item.json.rascunho;

    // Extrai o título do post a partir do texto original
    let postTitle = "Título Padrão";
    const titleMatch = markdownText.match(/^#+\s*(.*)/);
    if (titleMatch && titleMatch[1]) {
        postTitle = titleMatch[1];
    }

    // Executa os dois passos de processamento
    const processedHtml = processHTMLForWordPress(htmlContent);
    const finalHtmlWithCss = addElaborateCSS(processedHtml);

    // Cria o objeto final para enviar ao WordPress
    const requestBody = {
      status: "publish",
      title: postTitle,
      content: finalHtmlWithCss
    };

    // Retorna o objeto para ser usado pelo nó HTTP Request
    return [requestBody];

} catch (error) {
    // Em caso de erro, formata a mensagem para facilitar a depuração
    error.name = `ERRO NO CÓDIGO: ${error.name}`;
    return [{ json: { error: error.message, stack: error.stack, status: "error" } }];
}

const formatImagesInHtml = (html) => {
    return html.replace(/<img\s+src=["']([^"']+)["']\s*[^>]*>/g, 
        (match, src) => {
            return `<div style="text-align: center;"><img src="${src}" alt="" width="300" height="250" /></div>`;
        }
    );
};

// Exemplo de uso no n8n:
const htmlContent = $item("0").$node["Markdown"].json["data"];
const formattedHtml = formatImagesInHtml(htmlContent);

return [{ formattedHtml }];

const query = $input.item.json.output || 'praias cultura Fortaleza';
const apiKey = '87cb07f073b68ad22fc7ff93dfcf6c006a93b3f84e78f29e9fd27eca1a712da1';

// Constrói a URL manualmente
const baseUrl = 'https://serpapi.com/search';
const params = [
  'engine=google_images',
  'q=' + encodeURIComponent(query).replace(/%20/g, '+'),
  'google_domain=google.com.br',
  'gl=br',
  'hl=pt-br',
  'num=5',
  'api_key=' + apiKey
];

const fullUrl = baseUrl + '?' + params.join('&');

return {
  json: {
    url: fullUrl,
    query: query
  }
};
